import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Solution {
    public List<Integer> findSubstring(String s, String[] words) {
        List<Integer> answer = new ArrayList<>();
        int wordLength = words[0].length();
        int wordCount = words.length;
        int totalLength = wordLength * wordCount;
        if (s.length() < totalLength) {
            return answer;
        }

        Map<String, Integer> target = new HashMap<>();
        for (String word : words) {
            target.put(word, target.getOrDefault(word, 0) + 1);
        }

        for (int offset = 0; offset < wordLength; offset++) {
            Map<String, Integer> window = new HashMap<>();
            int left = offset;
            int matched = 0;
            for (int right = offset; right + wordLength <= s.length(); right += wordLength) {
                String token = s.substring(right, right + wordLength);
                if (!target.containsKey(token)) {
                    window.clear();
                    matched = 0;
                    left = right + wordLength;
                    continue;
                }

                window.put(token, window.getOrDefault(token, 0) + 1);
                matched++;
                while (window.get(token) > target.get(token)) {
                    String remove = s.substring(left, left + wordLength);
                    window.put(remove, window.get(remove) - 1);
                    matched--;
                    left += wordLength;
                }

                if (matched == wordCount) {
                    answer.add(left);
                    String remove = s.substring(left, left + wordLength);
                    window.put(remove, window.get(remove) - 1);
                    matched--;
                    left += wordLength;
                }
            }
        }
        return answer;
    }
}

