import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Solution {
    public List<Integer> findSubstring(String s, String[] words) {
        List<Integer> answer = new ArrayList<>();
        int wordLength = words[0].length();
        int wordCount = words.length;
        int totalLength = wordLength * wordCount;
        if (s.length() < totalLength) {
            return answer;
        }

        Map<String, Integer> ids = new HashMap<>();
        int[] required = new int[wordCount];
        int unique = 0;
        for (String word : words) {
            Integer id = ids.get(word);
            if (id == null) {
                id = unique++;
                ids.put(word, id);
            }
            required[id]++;
        }

        for (int offset = 0; offset < wordLength; offset++) {
            int[] window = new int[unique];
            int matched = 0;
            int left = offset;
            for (int right = offset; right + wordLength <= s.length(); right += wordLength) {
                String token = s.substring(right, right + wordLength);
                Integer id = ids.get(token);
                if (id == null) {
                    Arrays.fill(window, 0);
                    matched = 0;
                    left = right + wordLength;
                    continue;
                }

                window[id]++;
                matched++;
                while (window[id] > required[id]) {
                    int removeId = ids.get(s.substring(left, left + wordLength));
                    window[removeId]--;
                    matched--;
                    left += wordLength;
                }

                if (matched == wordCount) {
                    answer.add(left);
                    int removeId = ids.get(s.substring(left, left + wordLength));
                    window[removeId]--;
                    matched--;
                    left += wordLength;
                }
            }
        }
        return answer;
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Solution {
    public List<Integer> findSubstring(String s, String[] words) {
        List<Integer> answer = new ArrayList<>();
        int wordLength = words[0].length();
        int wordCount = words.length;
        int totalLength = wordLength * wordCount;
        if (s.length() < totalLength) {
            return answer;
        }

        Map<String, Integer> ids = new HashMap<>();
        int[] required = new int[wordCount];
        int unique = 0;
        for (String word : words) {
            Integer id = ids.get(word);
            if (id == null) {
                id = unique++;
                ids.put(word, id);
            }
            required[id]++;
        }

        for (int offset = 0; offset < wordLength; offset++) {
            int tokenCount = (s.length() - offset) / wordLength;
            int[] tokenIds = new int[tokenCount];
            for (int i = 0; i < tokenCount; i++) {
                int start = offset + i * wordLength;
                Integer id = ids.get(s.substring(start, start + wordLength));
                tokenIds[i] = id == null ? -1 : id;
            }

            int[] window = new int[unique];
            int left = 0;
            int matched = 0;
            for (int right = 0; right < tokenIds.length; right++) {
                int id = tokenIds[right];
                if (id == -1) {
                    Arrays.fill(window, 0);
                    left = right + 1;
                    matched = 0;
                    continue;
                }

                window[id]++;
                matched++;
                while (window[id] > required[id]) {
                    window[tokenIds[left]]--;
                    left++;
                    matched--;
                }

                if (matched == wordCount) {
                    answer.add(offset + left * wordLength);
                    window[tokenIds[left]]--;
                    left++;
                    matched--;
                }
            }
        }
        return answer;
    }
}
